namespace {QString escaped(const QString&s){return QString::fromLatin1(QUrl::toPercentEncoding(s));}}
void OmadashWindow::restoreAccounts(){if(!cache->ready())return;for(auto address:cache->accounts())keyring->read(address,[this,address](QByteArray value,QString error){if(!error.isEmpty()){notify(address+": "+error);return;}QFile f(QCoreApplication::applicationDirPath()+"/../.state/google-client.json");auto*c=makeGoogleClient();QString e;if(!f.open(QIODevice::ReadOnly)||!c->configure(f.readAll(),&e)||!c->restoreCredentials(value)){c->deleteLater();notify("Reconnect "+address+" from Accounts.");return;}registerAccount(address,c,false);rememberAccount(address,c);startSync(address);});}
void OmadashWindow::rememberAccount(const QString&a,GoogleClient*c){if(!persistPreferences||c->credentials().isEmpty())return;auto persist=[this,a,c]{auto bytes=c->credentials();if(bytes.isEmpty())return;keyring->write(a,bytes,[this,a](QByteArray,QString error){if(!sessions.contains(a))return;if(error.isEmpty()){cache->setMeta(a,"remember","1");notify("Account remembered securely · "+a);}else notify(error);});};connect(c,&GoogleClient::credentialsChanged,this,persist);persist();}
void OmadashWindow::startSync(const QString&a){if(!cache->ready()||syncs.contains(a)||!sessions.contains(a))return;auto*s=new MailSync(sessions[a].client,cache.get(),a,this);syncs[a]=s;connect(s,&MailSync::updated,this,&OmadashWindow::refreshCached);connect(s,&MailSync::progress,this,[this](QString a,QString message){if(a==account&&!actionBusy&&draftJobs.isEmpty())notify(message);});s->start();}
void OmadashWindow::refreshCached(const QString&a){if(!sessions.contains(a))return;auto items=cache->threads(a);sessions[a].loaded=true;sessions[a].stale=false;if(a!=account){sessions[a].threads=items;return;}if(loading||view=="search"||pages->currentIndex()!=0)return;QString selected=inbox->currentItem()?inbox->currentItem()->data(Qt::UserRole+1).toJsonObject()["id"].toString():QString();store.threads=items;sessions[a].threads=items;refreshInbox();for(int i=0;i<inbox->count();++i)if(inbox->item(i)->data(Qt::UserRole+1).toJsonObject()["id"]==selected)inbox->setCurrentRow(i);}
void OmadashWindow::refreshThread(const QString&a,const QString&id){if(!sessions.contains(a))return;sessions[a].client->get("gmail/v1/users/me/threads/"+escaped(id),{{"format","full"}},[this,a,id](QJsonObject data,QString error){if(!sessions.contains(a))return;if(error.isEmpty())cache->putThread(a,GoogleClient::normalizeThread(data,a));else if(data["_httpStatus"].toInt()==404)cache->removeThread(a,id);else{notify(error);return;}if(a==account&&view=="search"){if(pages->currentIndex()!=0)return;auto updated=cache->thread(a,id);for(int i=0;i<store.threads.size();++i)if(store.threads[i].toObject()["id"]==id){if(updated.isEmpty())store.threads.removeAt(i);else store.threads[i]=updated;break;}if(pages->currentIndex()==0)refreshInbox();}else refreshCached(a);});}
void OmadashWindow::loadGoogle(bool more){if(!live)return;QString owner=account;auto*c=google;int gen=++mailGeneration;loading=true;QString q=view=="search"?query:view=="inbox"?"in:inbox":view=="archive"?"-in:inbox -in:trash -in:spam":view=="starred"?"is:starred":view=="trash"?"in:trash":"";loadedQuery=q;QString token=more?pageToken:QString();if(!more){pages->setCurrentIndex(0);threadIndex=-1;if(view=="search"){if(!query.contains(':')&&!query.trimmed().isEmpty())store.threads=cache->search(owner,query);else{QJsonArray matched;for(auto t:cache->threads(owner)){QString error;if(store.matches(t.toObject(),query,&error)&&error.isEmpty())matched.append(t);}store.threads=matched;}}else store.threads=cache->threads(owner);pageToken.clear();}refreshInbox();notify("Showing cached mail · Checking Gmail…");c->get("gmail/v1/users/me/threads",{{"q",q},{"maxResults","50"},{"pageToken",token},{"includeSpamTrash",view=="trash"?"true":"false"}},[this,c,owner,gen,more](QJsonObject list,QString error){if(gen!=mailGeneration||owner!=account)return;if(!error.isEmpty()){loading=false;notify(error+" Cached mail remains available.");refreshInbox();return;}auto ids=list["threads"].toArray();QString next=list["nextPageToken"].toString();struct Batch{int next=0,active=0;QJsonArray results;bool failed=false;};auto b=std::make_shared<Batch>();auto pump=std::make_shared<std::function<void()>>();std::weak_ptr<std::function<void()>> weak=pump;*pump=[this,c,owner,gen,more,ids,next,b,weak]{auto keep=weak.lock();if(!keep||gen!=mailGeneration||owner!=account)return;if(b->next>=ids.size()&&b->active==0){loading=false;pageToken=next;if(pages->currentIndex()!=0){notify("Mail refreshed in the background.");return;}if(view=="search"){if(!more&&!b->failed)store.threads={};for(auto v:b->results){bool found=false;for(int i=0;i<store.threads.size();++i)if(store.threads[i].toObject()["id"]==v.toObject()["id"]){store.threads[i]=v;found=true;break;}if(!found)store.threads.append(v);}}else store.threads=cache->threads(owner);QList<QJsonObject> ordered;for(auto item:store.threads)ordered<<item.toObject();std::stable_sort(ordered.begin(),ordered.end(),[](const auto&a,const auto&b){return a["date"].toString()>b["date"].toString();});store.threads={};for(auto item:ordered)store.threads.append(item);refreshInbox();cacheAccount();notify(b->failed?"Some messages could not refresh. Cached mail is available.":"Mail refreshed · Background sync active");return;}while(b->active<4&&b->next<ids.size()){auto item=ids[b->next++].toObject();QString id=item["id"].toString();++b->active;c->get("gmail/v1/users/me/threads/"+escaped(id),{{"format","full"}},[this,owner,b,keep](QJsonObject data,QString e){--b->active;if(e.isEmpty()){auto t=GoogleClient::normalizeThread(data,owner);if(!cache->putThread(owner,t))b->failed=true;b->results.append(cache->thread(owner,t["id"].toString()));}else b->failed=true;(*keep)();});}};(*pump)();});}
void OmadashWindow::liveAction(const QString&a){if(actionBusy)return;if(!google->canModify()){drawer("Enable Gmail actions to update your mailbox, save drafts, and send.",{{"Enable Gmail actions…","enable"}},[this](QString){connectGoogle(true);});return;}if(!QStringList{"archive","trash","restore","star","unread","read"}.contains(a)){notify("That action is not available yet.");return;}QStringList ids;if(pages->currentIndex()==1&&threadIndex>=0)ids<<store.threads[threadIndex].toObject()["id"].toString();else if(pages->currentIndex()==0)for(auto*i:inbox->selectedItems())ids<<i->data(Qt::UserRole+1).toJsonObject()["id"].toString();if(ids.isEmpty())return;QString owner=account;auto*c=google;bool reader=pages->currentIndex()==1;QString readerId=reader?ids.first():QString();actionBusy=true;auto index=std::make_shared<int>(0);auto records=std::make_shared<QJsonArray>();auto step=std::make_shared<std::function<void()>>();std::weak_ptr<std::function<void()>> weak=step;*step=[this,c,a,owner,ids,index,records,reader,readerId,weak]{auto keep=weak.lock();if(!keep)return;if(!sessions.contains(owner)){actionBusy=false;return;}if(*index>=ids.size()){actionBusy=false;gmailUndo.append(QJsonObject{{"account",owner},{"records",*records}});if(owner==account&&reader&&pages->currentIndex()==1&&threadIndex>=0&&store.threads[threadIndex].toObject()["id"]==readerId)back();notify("Gmail updated · Z to undo");return;}QString id=ids[(*index)++];GmailActions::apply(c,id,a,[this,owner,id,records,keep](QJsonObject result,QString error){if(error.isEmpty()){records->append(result["undo"]);refreshThread(owner,id);(*keep)();}else{actionBusy=false;if(!records->isEmpty())gmailUndo.append(QJsonObject{{"account",owner},{"records",*records}});refreshThread(owner,id);notify(error);}});};(*step)();}
void OmadashWindow::undoGmail(){if(actionBusy)return;int at=-1;for(int i=gmailUndo.size()-1;i>=0;--i)if(gmailUndo[i]["account"]==account){at=i;break;}if(at<0){notify("No Gmail action to undo for this account.");return;}auto group=gmailUndo.takeAt(at);auto records=group["records"].toArray();QString owner=account;auto*c=google;actionBusy=true;auto index=std::make_shared<int>(records.size()-1);auto step=std::make_shared<std::function<void()>>();std::weak_ptr<std::function<void()>> weak=step;*step=[this,c,records,owner,index,weak]{auto keep=weak.lock();if(!keep)return;if(*index<0){actionBusy=false;notify("Gmail action undone.");return;}auto record=records[(*index)--].toObject();GmailActions::undo(c,record,[this,owner,record,records,index,keep](QJsonObject,QString error){refreshThread(owner,record["thread"].toString());if(error.isEmpty())(*keep)();else{actionBusy=false;QJsonArray remaining;for(int i=0;i<=*index+1;++i)remaining.append(records[i]);gmailUndo.append(QJsonObject{{"account",owner},{"records",remaining}});notify("Undo stopped: "+error+" Press Z to retry after checking Gmail.");}});};(*step)();}
void OmadashWindow::saveLocalDrafts(){if(!cache)return;for(auto id:store.drafts.keys())if(!cache->putDraft(id,store.drafts[id].toObject()))notify("Draft could not be saved locally: "+cache->error);}
void OmadashWindow::openLiveDraft(const QString&id){persistDraft();draftId=id;bodyEdit=nullptr;toEdit=nullptr;auto d=store.drafts[id].toObject();if(d.isEmpty())return;if(d["account"].toString()!=account)return;while(auto*item=composeLayout->takeAt(0)){if(item->widget())item->widget()->deleteLater();delete item;}auto*backButton=new QPushButton("← Save & close");connect(backButton,&QPushButton::clicked,this,&OmadashWindow::back);composeLayout->addWidget(backButton,0,Qt::AlignLeft);composeLayout->addWidget(composer(),1);pages->setCurrentIndex(2);saveLocalDrafts();bodyEdit->setFocus();}
void OmadashWindow::addDraftAttachments(){if(draftJobs.contains(draftId))return;persistDraft();QStringList paths=QFileDialog::getOpenFileNames(this,"Attach files",QDir::homePath()+"/Downloads");if(paths.isEmpty())return;auto d=store.drafts[draftId].toObject();auto files=d["attachments"].toArray();qint64 total=0;for(auto f:files)total+=QByteArray::fromBase64(f.toObject()["data"].toString().toLatin1()).size();for(auto path:paths){QFile file(path);if(!file.open(QIODevice::ReadOnly)||file.size()+total>18*1024*1024){notify("Could not attach file, or attachments exceed 18 MB.");return;}auto data=file.readAll();total+=data.size();files.append(QJsonObject{{"name",QFileInfo(path).fileName()},{"mime",QMimeDatabase().mimeTypeForFile(path).name()},{"data",QString::fromLatin1(data.toBase64())}});}d["attachments"]=files;store.drafts[draftId]=d;openLiveDraft(draftId);}
void OmadashWindow::syncDraft(const QString&id,bool send){if(draftJobs.contains(id)||!store.drafts.contains(id))return;auto d=store.drafts[id].toObject();QString owner=d["account"].toString();if(!sessions.contains(owner)){notify("Connect the draft's account first.");return;}auto*c=sessions[owner].client;if(!c->canModify()){notify("Enable Gmail actions to sync or send this draft.");return;}if(d["uncertain"].toBool()){notify("The previous request was not confirmed. Check Gmail Drafts/Sent before trying again; this local draft is preserved.");return;}if(send&&d["to"].toString().trimmed().isEmpty()&&d["cc"].toString().trimmed().isEmpty()&&d["bcc"].toString().trimmed().isEmpty()){notify("Add a recipient first.");return;}if(d["outgoingMessageId"].toString().isEmpty()){d["outgoingMessageId"]="<"+QUuid::createUuid().toString(QUuid::WithoutBraces)+"@omadash.local>";store.drafts[id]=d;}QString error;auto raw=Mime::message(d,owner,&error);if(!error.isEmpty()){notify(error);return;}QJsonObject message{{"raw",QString::fromLatin1(raw.toBase64(QByteArray::Base64UrlEncoding|QByteArray::OmitTrailingEquals))}};if(d["mode"]!="forward"&&!d["sourceId"].toString().isEmpty()&&!d["threadId"].toString().isEmpty())message["threadId"]=d["threadId"];QString remote=d["gmailDraftId"].toString();draftJobs.insert(id);d["uncertain"]=true;store.drafts[id]=d;cache->putDraft(id,d);if(send){composePage->setEnabled(false);threadPage->setEnabled(false);}notify(send?"Sending message…":"Saving draft to Gmail…");auto fail=[this,id,send](QJsonObject result,QString error){draftJobs.remove(id);if(send){composePage->setEnabled(true);threadPage->setEnabled(true);}if(store.drafts.contains(id)){auto d=store.drafts[id].toObject();d["uncertain"]=result["_uncertain"].toBool();store.drafts[id]=d;cache->putDraft(id,d);}notify(error+" Your local draft is preserved.");};c->mutate(remote.isEmpty()?"POST":"PUT","gmail/v1/users/me/drafts"+(remote.isEmpty()?QString():"/"+escaped(remote)),QJsonObject{{"message",message}},[this,c,id,owner,d,send,fail](QJsonObject result,QString error){if(!error.isEmpty()){fail(result,error);return;}if(!store.drafts.contains(id)){fail({},"Draft is no longer available.");return;}auto current=store.drafts[id].toObject();current["gmailDraftId"]=result["id"];current["uncertain"]=send;store.drafts[id]=current;cache->putDraft(id,current);if(!send){draftJobs.remove(id);bool changed=false;for(auto key:{"to","cc","bcc","subject","body","attachments"})if(current[key]!=d[key])changed=true;if(changed)QTimer::singleShot(0,this,[this,id]{syncDraft(id);});else notify("Draft saved to Gmail.");return;}c->mutate("POST","gmail/v1/users/me/drafts/send",QJsonObject{{"id",result["id"]}},[this,id,owner,fail](QJsonObject sent,QString e){if(!e.isEmpty()){fail(sent,e);return;}draftJobs.remove(id);composePage->setEnabled(true);threadPage->setEnabled(true);store.drafts.remove(id);cache->removeDraft(id);if(draftId==id){draftId.clear();bodyEdit=nullptr;toEdit=nullptr;pages->setCurrentIndex(0);}refreshThread(owner,sent["threadId"].toString());notify("Message sent from "+owner);});});}
